143	const getElementPointForSelection = (
144	  element: ExcalidrawElement,
145	): GlobalPoint => {
146	  const { x, y, width, height, angle } = element;
147	  const target = pointFrom<GlobalPoint>(
148	    x +
149	      (isLinearElement(element) || isFreeDrawElement(element) ? 0 : width / 2),
150	    y,
151	  );
152	  let center: GlobalPoint;
153	
154	  if (isLinearElement(element)) {
155	    const bounds = getElementPointsCoords(element, element.points);
156	    center = pointFrom(
157	      (bounds[0] + bounds[2]) / 2,
158	      (bounds[1] + bounds[3]) / 2,
159	    );
160	  } else {
161	    center = pointFrom(x + width / 2, y + height / 2);
162	  }
163	
164	  if (isTextElement(element)) {
165	    return center;
166	  }
167	
168	  return pointRotateRads(target, center, angle);
169	};
