1898	const findFocusPointForEllipse = (
1899	  ellipse: ExcalidrawEllipseElement,
1900	  // Between -1 and 1 (not 0) the relative size of the "focus image" of
1901	  // the element on which the focus point lies
1902	  relativeDistance: number,
1903	  // The point for which we're trying to find the focus point, relative
1904	  // to the ellipse center.
1905	  point: GA.Point,
1906	): GA.Point => {
1907	  const relativeDistanceAbs = Math.abs(relativeDistance);
1908	  const a = (ellipse.width * relativeDistanceAbs) / 2;
1909	  const b = (ellipse.height * relativeDistanceAbs) / 2;
1910	
1911	  const orientation = Math.sign(relativeDistance);
1912	  const [px, pyo] = GAPoint.toTuple(point);
1913	
1914	  // The calculation below can't handle py = 0
1915	  const py = pyo === 0 ? 0.0001 : pyo;
1916	
1917	  const squares = px ** 2 * b ** 2 + py ** 2 * a ** 2;
1918	  // Tangent mx + ny + 1 = 0
1919	  const m =
1920	    (-px * b ** 2 +
1921	      orientation * py * Math.sqrt(Math.max(0, squares - a ** 2 * b ** 2))) /
1922	    squares;
1923	
1924	  let n = (-m * px - 1) / py;
1925	
1926	  if (n === 0) {
