321	    h.setState({
322	      selectedElementIds: elements.reduce(
323	        (acc, e) => ({
324	          ...acc,
325	          [e.id]: true,
326	        }),
327	        {},
328	      ),
329	    });
330	  });
331	  let handleCoords: TransformHandle | undefined;
332	  if (elements.length === 1) {
333	    handleCoords = getTransformHandles(
334	      elements[0],
335	      h.state.zoom,
336	      arrayToMap(h.elements),
337	      "mouse",
338	      {},
339	    )[handle];
340	  } else {
341	    const [x1, y1, x2, y2] = getCommonBounds(elements);
342	    const isFrameSelected = elements.some(isFrameLikeElement);
343	    const transformHandles = getTransformHandlesFromCoords(
344	      [x1, y1, x2, y2, (x1 + x2) / 2, (y1 + y2) / 2],
345	      0 as Radians,
346	      h.state.zoom,
347	      "mouse",
348	      isFrameSelected ? OMIT_SIDES_FOR_FRAME : OMIT_SIDES_FOR_MULTIPLE_ELEMENTS,
349	    );
350	    handleCoords = transformHandles[handle];
351	  }
352	
353	  if (!handleCoords) {
354	    throw new Error(`There is no "${handle}" handle for this selection`);
355	  }
356	
357	  const clientX = handleCoords[0] + handleCoords[2] / 2;
358	  const clientY = handleCoords[1] + handleCoords[3] / 2;
359	
360	  Keyboard.withModifierKeys(keyboardModifiers, () => {
361	    mouse.reset();
362	    mouse.down(clientX, clientY);
363	    mouse.move(mouseMove[0], mouseMove[1]);
364	    mouse.up();
365	  });
