368	const proxy = <T extends ExcalidrawElement>(
369	  element: T,
370	): typeof element & {
371	  /** Returns the actual, current element from the elements array, instead of
372	      the proxy */
373	  get(): typeof element;
374	} => {
375	  return new Proxy(
376	    {},
377	    {
378	      get(target, prop) {
379	        const currentElement = h.elements.find(
380	          ({ id }) => id === element.id,
381	        ) as any;
382	        if (prop === "get") {
383	          if (currentElement.hasOwnProperty("get")) {
384	            throw new Error(
385	              "trying to get `get` test property, but ExcalidrawElement seems to define its own",
386	            );
387	          }
388	          return () => currentElement;
389	        }
390	        return currentElement[prop];
391	      },
392	    },
393	  ) as any;
394	};
