 999	export const snapToMid = (
1000	  element: ExcalidrawBindableElement,
1001	  p: GlobalPoint,
1002	  tolerance: number = 0.05,
1003	): GlobalPoint => {
1004	  const { x, y, width, height, angle } = element;
1005	  const center = pointFrom<GlobalPoint>(
1006	    x + width / 2 - 0.1,
1007	    y + height / 2 - 0.1,
1008	  );
1009	  const nonRotated = pointRotateRads(p, center, -angle as Radians);
1010	
1011	  // snap-to-center point is adaptive to element size, but we don't want to go
1012	  // above and below certain px distance
1013	  const verticalThrehsold = clamp(tolerance * height, 5, 80);
1014	  const horizontalThrehsold = clamp(tolerance * width, 5, 80);
1015	
1016	  if (
1017	    nonRotated[0] <= x + width / 2 &&
1018	    nonRotated[1] > center[1] - verticalThrehsold &&
1019	    nonRotated[1] < center[1] + verticalThrehsold
1020	  ) {
1021	    // LEFT
1022	    return pointRotateRads(
1023	      pointFrom(x - FIXED_BINDING_DISTANCE, center[1]),
1024	      center,
1025	      angle,
1026	    );
1027	  } else if (
1028	    nonRotated[1] <= y + height / 2 &&
1029	    nonRotated[0] > center[0] - horizontalThrehsold &&
1030	    nonRotated[0] < center[0] + horizontalThrehsold
1031	  ) {
1032	    // TOP
1033	    return pointRotateRads(
1034	      pointFrom(center[0], y - FIXED_BINDING_DISTANCE),
1035	      center,
1036	      angle,
1037	    );
1038	  } else if (
1039	    nonRotated[0] >= x + width / 2 &&
1040	    nonRotated[1] > center[1] - verticalThrehsold &&
1041	    nonRotated[1] < center[1] + verticalThrehsold
1042	  ) {
1043	    // RIGHT
1044	    return pointRotateRads(
1045	      pointFrom(x + width + FIXED_BINDING_DISTANCE, center[1]),
1046	      center,
1047	      angle,
1048	    );
1049	  } else if (
1050	    nonRotated[1] >= y + height / 2 &&
1051	    nonRotated[0] > center[0] - horizontalThrehsold &&
1052	    nonRotated[0] < center[0] + horizontalThrehsold
1053	  ) {
1054	    // DOWN
1055	    return pointRotateRads(
1056	      pointFrom(center[0], y + height + FIXED_BINDING_DISTANCE),
