1091	        elementsMap,
1092	      ).fixedPoint;
1093	    const globalMidPoint = pointFrom<GlobalPoint>(
1094	      bindableElement.x + bindableElement.width / 2,
1095	      bindableElement.y + bindableElement.height / 2,
1096	    );
1097	    const global = pointFrom<GlobalPoint>(
