1261	// 1: Update elements not selected to point to duplicated elements
1262	// 2: Update duplicated elements to point to other duplicated elements
1263	export const fixBindingsAfterDuplication = (
1264	  sceneElements: readonly ExcalidrawElement[],
1265	  oldElements: readonly ExcalidrawElement[],
1266	  oldIdToDuplicatedId: Map<ExcalidrawElement["id"], ExcalidrawElement["id"]>,
1267	  // There are three copying mechanisms: Copy-paste, duplication and alt-drag.
1268	  // Only when alt-dragging the new "duplicates" act as the "old", while
1269	  // the "old" elements act as the "new copy" - essentially working reverse
1270	  // to the other two.
1271	  duplicatesServeAsOld?: "duplicatesServeAsOld" | undefined,
1272	): void => {
1273	  // First collect all the binding/bindable elements, so we only update
1274	  // each once, regardless of whether they were duplicated or not.
1275	  const allBoundElementIds: Set<ExcalidrawElement["id"]> = new Set();
1276	  const allBindableElementIds: Set<ExcalidrawElement["id"]> = new Set();
1277	  const shouldReverseRoles = duplicatesServeAsOld === "duplicatesServeAsOld";
1278	  const duplicateIdToOldId = new Map(
1279	    [...oldIdToDuplicatedId].map(([key, value]) => [value, key]),
1280	  );
1281	  oldElements.forEach((oldElement) => {
1282	    const { boundElements } = oldElement;
1283	    if (boundElements != null && boundElements.length > 0) {
1284	      boundElements.forEach((boundElement) => {
1285	        if (shouldReverseRoles && !oldIdToDuplicatedId.has(boundElement.id)) {
1286	          allBoundElementIds.add(boundElement.id);
1287	        }
1288	      });
1289	      allBindableElementIds.add(oldIdToDuplicatedId.get(oldElement.id)!);
1290	    }
1291	    if (isBindingElement(oldElement)) {
1292	      if (oldElement.startBinding != null) {
1293	        const { elementId } = oldElement.startBinding;
1294	        if (shouldReverseRoles && !oldIdToDuplicatedId.has(elementId)) {
1295	          allBindableElementIds.add(elementId);
1296	        }
1297	      }
1298	      if (oldElement.endBinding != null) {
1299	        const { elementId } = oldElement.endBinding;
1300	        if (shouldReverseRoles && !oldIdToDuplicatedId.has(elementId)) {
1300	        if (shouldReverseRoles && !oldIdToDuplicatedId.has(elementId)) {
1301	          allBindableElementIds.add(elementId);
1302	        }
1303	      }
1304	      if (oldElement.startBinding != null || oldElement.endBinding != null) {
1305	        allBoundElementIds.add(oldIdToDuplicatedId.get(oldElement.id)!);
1306	      }
1307	    }
1308	  });
1309	
1310	  // Update the linear elements
1311	  (
1312	    sceneElements.filter(({ id }) =>
1313	      allBoundElementIds.has(id),
1314	    ) as ExcalidrawLinearElement[]
1315	  ).forEach((element) => {
1316	    const { startBinding, endBinding } = element;
1317	    mutateElement(element, {
1318	      startBinding: newBindingAfterDuplication(
1319	        startBinding,
1320	        oldIdToDuplicatedId,
1321	      ),
1322	      endBinding: newBindingAfterDuplication(endBinding, oldIdToDuplicatedId),
1323	    });
1324	  });
1325	
1326	  // Update the bindable shapes
1327	  sceneElements
1328	    .filter(({ id }) => allBindableElementIds.has(id))
1329	    .forEach((bindableElement) => {
1330	      const oldElementId = duplicateIdToOldId.get(bindableElement.id);
1331	      const boundElements = sceneElements.find(
1332	        ({ id }) => id === oldElementId,
1333	      )?.boundElements;
1334	
1335	      if (boundElements && boundElements.length > 0) {
1336	        mutateElement(bindableElement, {
1337	          boundElements: boundElements.map((boundElement) =>
1338	            oldIdToDuplicatedId.has(boundElement.id)
1339	              ? {
1340	                  id: oldIdToDuplicatedId.get(boundElement.id)!,
1341	                  type: boundElement.type,
1342	                }
1343	              : boundElement,
1344	          ),
1345	        });
1346	      }
1347	    });
1348	};
1349	
1350	const newBindingAfterDuplication = (
1351	  binding: PointBinding | null,
1352	  oldIdToDuplicatedId: Map<ExcalidrawElement["id"], ExcalidrawElement["id"]>,
1353	): PointBinding | null => {
1354	  if (binding == null) {
1355	    return null;
1356	  }
1357	  return {
1358	    ...binding,
1359	    elementId: oldIdToDuplicatedId.get(binding.elementId) ?? binding.elementId,
1360	  };
1361	};
