1498	const ellipseParamsForTest = (
1499	  element: ExcalidrawEllipseElement,
1500	  point: GlobalPoint,
1501	  elementsMap: ElementsMap,
1502	): [GA.Point, GA.Line] => {
1503	  const [, pointRel, hwidth, hheight] = pointRelativeToElement(
1504	    element,
1505	    point,
1506	    elementsMap,
1507	  );
1508	  const [px, py] = GAPoint.toTuple(pointRel);
1509	
1510	  // We're working in positive quadrant, so start with `t = 45deg`, `tx=cos(t)`
1511	  let tx = 0.707;
1512	  let ty = 0.707;
1513	
1514	  const a = hwidth;
1515	  const b = hheight;
1516	
1517	  // This is a numerical method to find the params tx, ty at which
1518	  // the ellipse has the closest point to the given point
1519	  [0, 1, 2, 3].forEach((_) => {
1520	    const xx = a * tx;
1521	    const yy = b * ty;
1522	
1523	    const ex = ((a * a - b * b) * tx ** 3) / a;
1524	    const ey = ((b * b - a * a) * ty ** 3) / b;
1525	
1526	    const rx = xx - ex;
1527	    const ry = yy - ey;
1528	
1529	    const qx = px - ex;
1530	    const qy = py - ey;
1531	
1532	    const r = Math.hypot(ry, rx);
1533	    const q = Math.hypot(qy, qx);
1534	
1535	    tx = Math.min(1, Math.max(0, ((qx * r) / q + ex) / a));
1536	    ty = Math.min(1, Math.max(0, ((qy * r) / q + ey) / b));
1537	    const t = Math.hypot(ty, tx);
1538	    tx /= t;
1539	    ty /= t;
1540	  });
1541	
1542	  const closestPoint = GA.point(a * tx, b * ty);
1543	
1544	  const tangent = GALine.orthogonalThrough(pointRel, closestPoint);
1545	  return [pointRel, tangent];
1546	};
