1548	// Returns:
1549	//   1. the point relative to the elements (x, y) position
1550	//   2. the point relative to the element's center with positive (x, y)
1551	//   3. half element width
1552	//   4. half element height
1553	//
1554	// Note that for linear elements the (x, y) position is not at the
1555	// top right corner of their boundary.
1556	//
1557	// Rectangles, diamonds and ellipses are symmetrical over axes,
1558	// and other elements have a rectangular boundary,
1559	// so we only need to perform hit tests for the positive quadrant.
1560	const pointRelativeToElement = (
1561	  element: ExcalidrawElement,
1562	  pointTuple: GlobalPoint,
1563	  elementsMap: ElementsMap,
1564	): [GA.Point, GA.Point, number, number] => {
1565	  const point = GAPoint.from(pointTuple);
1566	  const [x1, y1, x2, y2] = getElementAbsoluteCoords(element, elementsMap);
1567	  const center = coordsCenter(x1, y1, x2, y2);
1568	  // GA has angle orientation opposite to `rotate`
1569	  const rotate = GATransform.rotation(center, element.angle);
1570	  const pointRotated = GATransform.apply(rotate, point);
1571	  const pointRelToCenter = GA.sub(pointRotated, GADirection.from(center));
1572	  const pointRelToCenterAbs = GAPoint.abs(pointRelToCenter);
1573	  const elementPos = GA.offset(element.x, element.y);
1574	  const pointRelToPos = GA.sub(pointRotated, elementPos);
1575	  const halfWidth = (x2 - x1) / 2;
1576	  const halfHeight = (y2 - y1) / 2;
1577	  return [pointRelToPos, pointRelToCenterAbs, halfWidth, halfHeight];
1578	};
