1617	  const aRel = GATransform.apply(relateToCenter, GAPoint.from(a));
1618	  const bRel = GATransform.apply(relateToCenter, GAPoint.from(b));
1619	  const line = GALine.through(aRel, bRel);
1620	  const q = element.height / element.width;
1621	  const hwidth = element.width / 2;
1622	  const hheight = element.height / 2;
