620	// Supports translating, rotating and scaling `changedElement` with bound
621	// linear elements.
622	// Because scaling involves moving the focus points as well, it is
623	// done before the `changedElement` is updated, and the `newSize` is passed
624	// in explicitly.
625	export const updateBoundElements = (
626	  changedElement: NonDeletedExcalidrawElement,
627	  elementsMap: NonDeletedSceneElementsMap | SceneElementsMap,
628	  options?: {
629	    simultaneouslyUpdated?: readonly ExcalidrawElement[];
630	    newSize?: { width: number; height: number };
631	    changedElements?: Map<string, OrderedExcalidrawElement>;
632	    zoom?: AppState["zoom"];
633	  },
634	) => {
635	  const { newSize, simultaneouslyUpdated, changedElements, zoom } =
636	    options ?? {};
637	  const simultaneouslyUpdatedElementIds = getSimultaneouslyUpdatedElementIds(
638	    simultaneouslyUpdated,
639	  );
640	
641	  if (!isBindableElement(changedElement)) {
642	    return;
643	  }
644	
645	  boundElementsVisitor(elementsMap, changedElement, (element) => {
646	    if (!isLinearElement(element) || element.isDeleted) {
647	      return;
648	    }
649	
650	    // In case the boundElements are stale
651	    if (!doesNeedUpdate(element, changedElement)) {
652	      return;
653	    }
654	
655	    const bindings = {
656	      startBinding: maybeCalculateNewGapWhenScaling(
657	        changedElement,
658	        element.startBinding,
659	        newSize,
660	      ),
661	      endBinding: maybeCalculateNewGapWhenScaling(
662	        changedElement,
663	        element.endBinding,
664	        newSize,
665	      ),
666	    };
667	
668	    // `linearElement` is being moved/scaled already, just update the binding
669	    if (simultaneouslyUpdatedElementIds.has(element.id)) {
670	      mutateElement(element, bindings);
671	      return;
672	    }
673	
674	    const updates = bindableElementsVisitor(
675	      elementsMap,
676	      element,
677	      (bindableElement, bindingProp) => {
678	        if (
679	          bindableElement &&
680	          isBindableElement(bindableElement) &&
681	          (bindingProp === "startBinding" || bindingProp === "endBinding") &&
682	          changedElement.id === element[bindingProp]?.elementId
683	        ) {
684	          const point = updateBoundPoint(
685	            element,
686	            bindingProp,
687	            bindings[bindingProp],
688	            bindableElement,
689	            elementsMap,
690	          );
691	          if (point) {
692	            return {
693	              index:
694	                bindingProp === "startBinding" ? 0 : element.points.length - 1,
695	              point,
696	            };
697	          }
698	        }
699	
700	        return null;
701	      },
702	    ).filter(
703	      (
704	        update,
705	      ): update is NonNullable<{
706	        index: number;
707	        point: LocalPoint;
708	        isDragging?: boolean;
709	      }> => update !== null,
710	    );
711	
712	    LinearElementEditor.movePoints(
713	      element,
714	      updates,
715	      elementsMap,
716	      {
717	        ...(changedElement.id === element.startBinding?.elementId
718	          ? { startBinding: bindings.startBinding }
719	          : {}),
720	        ...(changedElement.id === element.endBinding?.elementId
721	          ? { endBinding: bindings.endBinding }
722	          : {}),
723	      },
724	      {
725	        changedElements,
726	        zoom,
727	      },
728	    );
729	
730	    const boundText = getBoundTextElement(element, elementsMap);
731	    if (boundText && !boundText.isDeleted) {
732	      handleBindTextResize(element, elementsMap, false);
733	    }
734	  });
735	};
