363	/**
364	 * Routing algorithm based on the A* path search algorithm.
365	 * @see https://www.geeksforgeeks.org/a-search-algorithm/
366	 *
367	 * Binary heap is used to optimize node lookup.
368	 * See {@link calculateGrid} for the grid calculation details.
369	 *
370	 * Additional modifications added due to aesthetic route reasons:
371	 * 1) Arrow segment direction change is penalized by specific linear constant (bendMultiplier)
372	 * 2) Arrow segments are not allowed to go "backwards", overlapping with the previous segment
373	 */
374	const astar = (
375	  start: Node,
376	  end: Node,
377	  grid: Grid,
378	  startHeading: Heading,
379	  endHeading: Heading,
380	  aabbs: Bounds[],
381	) => {
382	  const bendMultiplier = m_dist(start.pos, end.pos);
383	  const open = new BinaryHeap<Node>((node) => node.f);
384	
385	  open.push(start);
386	
387	  while (open.size() > 0) {
388	    // Grab the lowest f(x) to process next.  Heap keeps this sorted for us.
389	    const current = open.pop();
390	
391	    if (!current || current.closed) {
392	      // Current is not passable, continue with next element
393	      continue;
394	    }
395	
396	    // End case -- result has been found, return the traced path.
397	    if (current === end) {
398	      return pathTo(start, current);
399	    }
400	
401	    // Normal case -- move current from open to closed, process each of its neighbors.
402	    current.closed = true;
403	
404	    // Find all neighbors for the current node.
405	    const neighbors = getNeighbors(current.addr, grid);
406	
407	    for (let i = 0; i < 4; i++) {
408	      const neighbor = neighbors[i];
409	
410	      if (!neighbor || neighbor.closed) {
411	        // Not a valid node to process, skip to next neighbor.
412	        continue;
413	      }
414	
415	      // Intersect
416	      const neighborHalfPoint = pointScaleFromOrigin(
417	        neighbor.pos,
418	        current.pos,
419	        0.5,
420	      );
421	      if (
422	        isAnyTrue(
423	          ...aabbs.map((aabb) => pointInsideBounds(neighborHalfPoint, aabb)),
424	        )
425	      ) {
426	        continue;
427	      }
428	
429	      // The g score is the shortest distance from start to current node.
430	      // We need to check if the path we have arrived at this neighbor is the shortest one we have seen yet.
431	      const neighborHeading = neighborIndexToHeading(i as 0 | 1 | 2 | 3);
432	      const previousDirection = current.parent
433	        ? vectorToHeading(vectorFromPoint(current.pos, current.parent.pos))
434	        : startHeading;
435	
436	      // Do not allow going in reverse
437	      const reverseHeading = flipHeading(previousDirection);
438	      const neighborIsReverseRoute =
439	        compareHeading(reverseHeading, neighborHeading) ||
440	        (gridAddressesEqual(start.addr, neighbor.addr) &&
441	          compareHeading(neighborHeading, startHeading)) ||
442	        (gridAddressesEqual(end.addr, neighbor.addr) &&
443	          compareHeading(neighborHeading, endHeading));
444	      if (neighborIsReverseRoute) {
445	        continue;
446	      }
447	
448	      const directionChange = previousDirection !== neighborHeading;
449	      const gScore =
450	        current.g +
451	        m_dist(neighbor.pos, current.pos) +
452	        (directionChange ? Math.pow(bendMultiplier, 3) : 0);
453	
454	      const beenVisited = neighbor.visited;
455	
456	      if (!beenVisited || gScore < neighbor.g) {
457	        const estBendCount = estimateSegmentCount(
458	          neighbor,
459	          end,
460	          neighborHeading,
461	          endHeading,
462	        );
463	        // Found an optimal (so far) path to this node.  Take score for node to see how good it is.
464	        neighbor.visited = true;
465	        neighbor.parent = current;
466	        neighbor.h =
467	          m_dist(end.pos, neighbor.pos) +
468	          estBendCount * Math.pow(bendMultiplier, 2);
469	        neighbor.g = gScore;
470	        neighbor.f = neighbor.g + neighbor.h;
471	        if (!beenVisited) {
472	          // Pushing to heap will put it in proper place based on the 'f' value.
473	          open.push(neighbor);
474	        } else {
475	          // Already seen the node, but since it has been rescored we need to reorder it in the heap
476	          open.rescoreElement(neighbor);
477	        }
478	      }
479	    }
480	  }
481	
482	  return null;
483	};
