505	const generateDynamicAABBs = (
506	  a: Bounds,
507	  b: Bounds,
508	  common: Bounds,
509	  startDifference?: [number, number, number, number],
510	  endDifference?: [number, number, number, number],
511	  disableSideHack?: boolean,
512	  startElementBounds?: Bounds | null,
513	  endElementBounds?: Bounds | null,
514	): Bounds[] => {
515	  const startEl = startElementBounds ?? a;
516	  const endEl = endElementBounds ?? b;
517	  const [startUp, startRight, startDown, startLeft] = startDifference ?? [
518	    0, 0, 0, 0,
519	  ];
520	  const [endUp, endRight, endDown, endLeft] = endDifference ?? [0, 0, 0, 0];
521	
522	  const first = [
523	    a[0] > b[2]
524	      ? a[1] > b[3] || a[3] < b[1]
525	        ? Math.min((startEl[0] + endEl[2]) / 2, a[0] - startLeft)
526	        : (startEl[0] + endEl[2]) / 2
527	      : a[0] > b[0]
528	      ? a[0] - startLeft
529	      : common[0] - startLeft,
530	    a[1] > b[3]
531	      ? a[0] > b[2] || a[2] < b[0]
532	        ? Math.min((startEl[1] + endEl[3]) / 2, a[1] - startUp)
533	        : (startEl[1] + endEl[3]) / 2
534	      : a[1] > b[1]
535	      ? a[1] - startUp
536	      : common[1] - startUp,
537	    a[2] < b[0]
538	      ? a[1] > b[3] || a[3] < b[1]
539	        ? Math.max((startEl[2] + endEl[0]) / 2, a[2] + startRight)
540	        : (startEl[2] + endEl[0]) / 2
541	      : a[2] < b[2]
542	      ? a[2] + startRight
543	      : common[2] + startRight,
544	    a[3] < b[1]
545	      ? a[0] > b[2] || a[2] < b[0]
546	        ? Math.max((startEl[3] + endEl[1]) / 2, a[3] + startDown)
547	        : (startEl[3] + endEl[1]) / 2
548	      : a[3] < b[3]
549	      ? a[3] + startDown
550	      : common[3] + startDown,
551	  ] as Bounds;
552	  const second = [
553	    b[0] > a[2]
554	      ? b[1] > a[3] || b[3] < a[1]
555	        ? Math.min((endEl[0] + startEl[2]) / 2, b[0] - endLeft)
556	        : (endEl[0] + startEl[2]) / 2
557	      : b[0] > a[0]
558	      ? b[0] - endLeft
559	      : common[0] - endLeft,
560	    b[1] > a[3]
561	      ? b[0] > a[2] || b[2] < a[0]
562	        ? Math.min((endEl[1] + startEl[3]) / 2, b[1] - endUp)
563	        : (endEl[1] + startEl[3]) / 2
564	      : b[1] > a[1]
565	      ? b[1] - endUp
566	      : common[1] - endUp,
567	    b[2] < a[0]
568	      ? b[1] > a[3] || b[3] < a[1]
569	        ? Math.max((endEl[2] + startEl[0]) / 2, b[2] + endRight)
570	        : (endEl[2] + startEl[0]) / 2
571	      : b[2] < a[2]
572	      ? b[2] + endRight
573	      : common[2] + endRight,
574	    b[3] < a[1]
575	      ? b[0] > a[2] || b[2] < a[0]
576	        ? Math.max((endEl[3] + startEl[1]) / 2, b[3] + endDown)
577	        : (endEl[3] + startEl[1]) / 2
578	      : b[3] < a[3]
579	      ? b[3] + endDown
580	      : common[3] + endDown,
