587	    first[3] - first[1] + second[3] - second[1] > c[3] - c[1] + 0.00000000001
588	  ) {
589	    const [endCenterX, endCenterY] = [
590	      (second[0] + second[2]) / 2,
591	      (second[1] + second[3]) / 2,
592	    ];
593	    if (b[0] > a[2] && a[1] > b[3]) {
594	      // BOTTOM LEFT
595	      const cX = first[2] + (second[0] - first[2]) / 2;
596	      const cY = second[3] + (first[1] - second[3]) / 2;
597	
598	      if (
599	        vectorCross(
600	          vector(a[2] - endCenterX, a[1] - endCenterY),
601	          vector(a[0] - endCenterX, a[3] - endCenterY),
602	        ) > 0
603	      ) {
604	        return [
605	          [first[0], first[1], cX, first[3]],
606	          [cX, second[1], second[2], second[3]],
607	        ];
608	      }
609	
610	      return [
611	        [first[0], cY, first[2], first[3]],
612	        [second[0], second[1], second[2], cY],
613	      ];
614	    } else if (a[2] < b[0] && a[3] < b[1]) {
615	      // TOP LEFT
616	      const cX = first[2] + (second[0] - first[2]) / 2;
617	      const cY = first[3] + (second[1] - first[3]) / 2;
618	
619	      if (
620	        vectorCross(
621	          vector(a[0] - endCenterX, a[1] - endCenterY),
622	          vector(a[2] - endCenterX, a[3] - endCenterY),
623	        ) > 0
624	      ) {
625	        return [
626	          [first[0], first[1], first[2], cY],
627	          [second[0], cY, second[2], second[3]],
628	        ];
629	      }
630	
631	      return [
632	        [first[0], first[1], cX, first[3]],
633	        [cX, second[1], second[2], second[3]],
634	      ];
635	    } else if (a[0] > b[2] && a[3] < b[1]) {
636	      // TOP RIGHT
637	      const cX = second[2] + (first[0] - second[2]) / 2;
638	      const cY = first[3] + (second[1] - first[3]) / 2;
639	
640	      if (
641	        vectorCross(
642	          vector(a[2] - endCenterX, a[1] - endCenterY),
643	          vector(a[0] - endCenterX, a[3] - endCenterY),
644	        ) > 0
645	      ) {
646	        return [
647	          [cX, first[1], first[2], first[3]],
648	          [second[0], second[1], cX, second[3]],
649	        ];
650	      }
651	
652	      return [
653	        [first[0], first[1], first[2], cY],
654	        [second[0], cY, second[2], second[3]],
655	      ];
656	    } else if (a[0] > b[2] && a[1] > b[3]) {
657	      // BOTTOM RIGHT
658	      const cX = second[2] + (first[0] - second[2]) / 2;
659	      const cY = second[3] + (first[1] - second[3]) / 2;
660	
661	      if (
662	        vectorCross(
663	          vector(a[0] - endCenterX, a[1] - endCenterY),
664	          vector(a[2] - endCenterX, a[3] - endCenterY),
665	        ) > 0
666	      ) {
667	        return [
668	          [cX, first[1], first[2], first[3]],
669	          [second[0], second[1], cX, second[3]],
670	        ];
671	      }
672	
673	      return [
674	        [first[0], cY, first[2], first[3]],
675	        [second[0], second[1], second[2], cY],
676	      ];
677	    }
678	  }
679	
680	  return [first, second];
