448	  static createElement<T extends DrawingToolName>(
449	    type: T,
450	    {
451	      position = 0,
452	      x = position,
453	      y = position,
454	      size = 10,
455	      width: initialWidth = size,
456	      height: initialHeight = initialWidth,
457	      angle = 0,
