459	    }: {
460	      position?: number;
461	      x?: number;
462	      y?: number;
463	      size?: number;
464	      width?: number;
465	      height?: number;
466	      angle?: number;
467	      points?: T extends "line" | "arrow" | "freedraw" ? LocalPoint[] : never;
468	    } = {},
469	  ): Element<T> & {
470	    /** Returns the actual, current element from the elements array, instead
