481	    UI.clickTool(type);
482	
483	    if (type === "text") {
484	      mouse.reset();
485	      mouse.click(x, y);
486	    } else if ((type === "line" || type === "arrow") && points.length > 2) {
487	      points.forEach((point) => {
488	        mouse.reset();
489	        mouse.click(x + point[0], y + point[1]);
490	      });
491	      Keyboard.keyPress(KEYS.ESCAPE);
492	    } else if (type === "freedraw" && points.length > 2) {
