2012	/**
2013	 * Tries to visit each bindable element (does not have to be found).
2014	 */
2015	const bindableElementsVisitor = <T>(
2016	  elements: ElementsMap,
2017	  element: ExcalidrawElement,
2018	  visit: BindableElementVisitingFunc<T>,
2019	): T[] => {
2020	  const result: T[] = [];
2021	
2022	  if (element.frameId) {
2023	    const id = element.frameId;
2024	    result.push(visit(elements.get(id), "frameId", id));
2025	  }
2026	
2027	  if (isBoundToContainer(element)) {
2028	    const id = element.containerId;
2029	    result.push(visit(elements.get(id), "containerId", id));
2030	  }
2031	
2032	  if (isArrowElement(element)) {
2033	    if (element.startBinding) {
2034	      const id = element.startBinding.elementId;
2035	      result.push(visit(elements.get(id), "startBinding", id));
2036	    }
2037	
2038	    if (element.endBinding) {
2039	      const id = element.endBinding.elementId;
2040	      result.push(visit(elements.get(id), "endBinding", id));
2041	    }
2042	  }
2043	
2044	  return result;
2045	};
