{"schema_version":"v4-test-constructor-v1","task_id":"excalidraw__excalidraw-9010","status":"test_bundle_proposed","repository_observations":{"framework":"Vitest 2.0.5 with jsdom, React Testing Library, and vitest-canvas-mock","package_manager":"Yarn 1.22.22 (declared in package.json)","working_directory":".","manifest_paths":["package.json","packages/excalidraw/package.json","yarn.lock"],"test_config_paths":["vitest.config.mts","setupTests.ts","tsconfig.json","packages/excalidraw/tsconfig.json"],"nearby_test_paths":["packages/excalidraw/tests/binding.test.tsx","packages/excalidraw/element/routing.test.tsx","packages/excalidraw/tests/move.test.tsx","packages/excalidraw/data/transform.test.ts","packages/excalidraw/tests/history.test.tsx","packages/excalidraw/tests/linearElementEditor.test.tsx","packages/excalidraw/tests/helpers/api.ts","packages/excalidraw/tests/helpers/ui.ts","packages/excalidraw/tests/test-utils.ts"],"author_test_paths":[]}, "behavioral_contract":[{"requirement_id":"interaction_temporal_understanding","observable_behavior":"During a pointer drag of one endpoint of an arrow, the global coordinates of the other endpoint, which was already bound to a source element, remain unchanged at every sampled move and at pointer-up.","preserved_behavior":"The dragged endpoint can bind to the destination element, and both elements retain the expected reciprocal arrow binding references.","oracle":"Numeric global endpoint geometry sampled before pointer-down, after pointer-down, during multiple pointer moves, and after pointer-up; final binding element IDs and reciprocal bound-element records."},{"requirement_id":"normal_arrow_binding_side_effects","observable_behavior":"Binding an endpoint through the rendered editor interaction does not cause an unrelated already-bound endpoint to be recomputed.","preserved_behavior":"Existing arrow binding semantics remain intact after the interaction.","oracle":"The untouched endpoint stability assertion is the regression oracle; binding metadata assertions guard the preserved domain behavior."}],"test_bundle":{"working_directory":".","test_command":"yarn test:app --run packages/excalidraw/tests/arrowBinding9010.test.tsx","stable_test_ids":["excalidraw-9010-endpoint-stability"],"predicted_transition":"candidate_f2p","files":[{"path":"packages/excalidraw/tests/arrowBinding9010.test.tsx","operation":"add","content":"import React from "react";
import { Excalidraw } from "../index";
import { LinearElementEditor } from "../element/linearElementEditor";
import { pointFrom } from "../../math";
import { API } from "./helpers/api";
import { Pointer } from "./helpers/ui";
import { render } from "./test-utils";

const { h } = window;

describe("arrow endpoint binding regression", () => {
  beforeEach(async () => {
    localStorage.clear();
    await render(<Excalidraw handleKeyboardGlobally={true} />);
  });

  it(
    "[excalidraw-9010-endpoint-stability] keeps the untouched binding point stationary while dragging the other endpoint",
    () => {
      const source = API.createElement({
        type: "rectangle",
        id: "source-9010",
        x: 0,
        y: 0,
        width: 100,
        height: 100,
        boundElements: [{ id: "arrow-9010", type: "arrow" }],
      });
      const destination = API.createElement({
        type: "rectangle",
        id: "destination-9010",
        x: 300,
        y: -200,
        width: 100,
        height: 100,
      });
      const arrow = API.createElement({
        type: "arrow",
        id: "arrow-9010",
        x: 110,
        y: 50,
        width: 500,
        height: 0,
        points: [pointFrom(0, 0), pointFrom(500, 0)],
        startBinding: {
          elementId: source.id,
          fixedPoint: null,
          focus: 0,
          gap: 10,
        },
        endBinding: null,
      });

      API.setElements([source, destination, arrow]);
      API.setAppState({
        selectedElementIds: { [arrow.id]: true },
        selectedLinearElement: new LinearElementEditor(arrow),
      });

      const readPoint = (index: number) =>
        LinearElementEditor.getPointAtIndexGlobalCoordinates(
          arrow,
          index,
          h.app.scene.getNonDeletedElementsMap(),
        );

      const startBefore = readPoint(0);
      const endBefore = readPoint(-1);
      const observedStartPoints = [startBefore];
      const mouse = new Pointer("mouse");

      mouse.downAt(endBefore[0], endBefore[1]);
      observedStartPoints.push(readPoint(0));
      mouse.moveTo(500, 200);
      observedStartPoints.push(readPoint(0));
      mouse.moveTo(
        destination.x,
        destination.y + destination.height / 2,
      );
      observedStartPoints.push(readPoint(0));
      mouse.upAt(destination.x, destination.y + destination.height / 2);
      observedStartPoints.push(readPoint(0));

      observedStartPoints.forEach((point) => {
        expect(point[0]).toBeCloseTo(startBefore[0], 5);
        expect(point[1]).toBeCloseTo(startBefore[1], 5);
      });

      expect(arrow.startBinding?.elementId).toBe(source.id);
      expect(arrow.endBinding?.elementId).toBe(destination.id);
      expect(source.boundElements).toEqual(
        expect.arrayContaining([{ id: arrow.id, type: "arrow" }]),
      );
      expect(destination.boundElements).toEqual(
        expect.arrayContaining([{ id: arrow.id, type: "arrow" }]),
      );
    },
  );
});
